function createEnv(sdk) {
  var STEPS = 500;
  var GROUND = 435;
  var TOUCH_Y = 415;
  var PAD_HALF = 62;
  var START_FUEL = 160;

  var rng, x, y, vx, vy, padX, fuel, tick, done;
  var lastAction = 0;
  var stars = [];
  var terms = [0, 0, 0, 0];
  var obs = new Float32Array(6);

  function reset(seed) {
    rng = sdk.rng(seed);
    padX = rng.range(300, 500);
    x = rng.range(130, 670);
    y = rng.range(82, 125);
    vx = rng.range(-0.65, 0.65);
    vy = rng.range(0.15, 0.55);
    fuel = START_FUEL;
    tick = 0;
    done = false;
    lastAction = 0;

    terms[0] = 0;
    terms[1] = 0;
    terms[2] = 0;
    terms[3] = 0;

    stars = [];
    for (var i = 0; i < 28; i++) {
      stars.push([rng.range(18, 782), rng.range(18, 310), rng.range(1, 2.2)]);
    }
  }

  function step(action) {
    if (done) return;

    var a = Math.floor(action);
    if (a < 0 || a > 3) a = 0;
    lastAction = 0;

    var ax = 0;
    var thrust = 0;
    var cost = 0;

    if (fuel > 0) {
      if (a === 1) {
        thrust = 0.034;
        cost = 1;
        lastAction = 1;
      } else if (a === 2) {
        ax = -0.025;
        cost = 0.7;
        lastAction = 2;
      } else if (a === 3) {
        ax = 0.025;
        cost = 0.7;
        lastAction = 3;
      }
    }

    if (cost > fuel) {
      cost = fuel;
      if (cost <= 0) {
        thrust = 0;
        ax = 0;
        lastAction = 0;
      }
    }
    fuel = Math.max(0, fuel - cost);
    terms[2] += cost / START_FUEL;

    vx = sdk.clamp(vx + ax, -4, 4);
    vy = sdk.clamp(vy + 0.013 - thrust, -3.5, 3.5);
    x += vx;
    y += vy;

    var horizontalProximity = Math.max(0, 1 - Math.abs(x - padX) / 360);
    var descentProgress = sdk.clamp((y - 82) / (TOUCH_Y - 82), 0, 1);
    var velocityQuality = Math.max(0, 1 - Math.abs(vx) / 2.5);
    var shaping = 0.7 * horizontalProximity * (0.65 + 0.35 * velocityQuality) +
      0.3 * descentProgress;
    terms[0] += shaping / STEPS;

    tick += 1;

    if (y >= TOUCH_Y) {
      var onPad = Math.abs(x - padX) <= PAD_HALF - 10;
      var gentle = Math.abs(vx) <= 0.65 && Math.abs(vy) <= 0.75;
      if (onPad && gentle) {
        terms[1] += 1;
      } else {
        terms[3] += 1;
      }
      y = TOUCH_Y;
      done = true;
    } else if (x < 12 || x > 788) {
      terms[3] += 1;
      done = true;
    } else if (tick >= STEPS) {
      done = true;
    }
  }

  function observe() {
    obs[0] = sdk.clamp((x - padX) / 400, -1, 1);
    obs[1] = sdk.clamp((GROUND - y) / (GROUND - 50), -1, 1);
    obs[2] = sdk.clamp(vx / 2.5, -1, 1);
    obs[3] = sdk.clamp(vy / 3.5, -1, 1);
    obs[4] = sdk.clamp((padX - 400) / 400, -1, 1);
    obs[5] = sdk.clamp(2 * fuel / START_FUEL - 1, -1, 1);
    return obs;
  }

  function render(draw, ghost) {
    if (!ghost) {
      draw.clear(sdk.colors.bg);

      for (var i = 0; i < stars.length; i++) {
        draw.circle(stars[i][0], stars[i][1], stars[i][2], sdk.colors.dim);
      }

      draw.rect(0, GROUND, 800, 65, sdk.colors.dim);
      draw.line(0, GROUND, 800, GROUND, sdk.colors.fg, 2);

      draw.rect(padX - PAD_HALF, GROUND - 5, PAD_HALF * 2, 8, sdk.colors.good);
      draw.line(padX - PAD_HALF, GROUND - 8, padX - PAD_HALF, GROUND + 4, sdk.colors.good, 2);
      draw.line(padX + PAD_HALF, GROUND - 8, padX + PAD_HALF, GROUND + 4, sdk.colors.good, 2);

      draw.text("PAD", padX - 14, GROUND - 17, sdk.colors.good, 12);
      draw.text("FUEL " + Math.round(fuel), 24, 30, sdk.colors.fg, 14);
    }

    if (lastAction === 1) {
      draw.poly([x - 5, y + 10, x + 5, y + 10, x, y + 23], sdk.colors.warn, true);
    } else if (lastAction === 2) {
      draw.poly([x + 10, y - 3, x + 21, y, x + 10, y + 3], sdk.colors.warn, true);
    } else if (lastAction === 3) {
      draw.poly([x - 10, y - 3, x - 21, y, x - 10, y + 3], sdk.colors.warn, true);
    }

    draw.poly([x - 9, y - 8, x + 9, y - 8, x + 7, y + 8, x - 7, y + 8], sdk.colors.accent, true);
    draw.line(x - 7, y + 7, x - 13, y + 14, sdk.colors.fg, 2);
    draw.line(x + 7, y + 7, x + 13, y + 14, sdk.colors.fg, 2);
    draw.line(x - 13, y + 14, x - 5, y + 14, sdk.colors.fg, 2);
    draw.line(x + 13, y + 14, x + 5, y + 14, sdk.colors.fg, 2);
    draw.circle(x, y - 1, 2, sdk.colors.fg);
  }

  return {
    reset: reset,
    step: step,
    observe: observe,
    get done() {
      return done;
    },
    terms: terms,
    render: render,
    humanAct: function (input) {
      if (input.held.has("ArrowUp")) return 1;
      if (input.held.has("ArrowLeft")) return 2;
      if (input.held.has("ArrowRight")) return 3;
      return 0;
    }
  };
}
